sap.ui.define([                                                                                                                                                                                                                                                
    "sap/ui/core/mvc/Controller",                                                                                                                                                                                                                              
    "sap/ui/model/json/JSONModel",                                                                                                                                                                                                                             
    "sap/ui/model/Filter",                                                                                                                                                                                                                                     
    "sap/ui/model/FilterOperator",                                                                                                                                                                                                                             
    "sap/ui/model/Sorter",                                                                                                                                                                                                                                     
    "sap/m/MessageToast",                                                                                                                                                                                                                                      
    "sap/m/MessageBox",                                                                                                                                                                                                                                        
    "sap/m/Dialog",                                                                                                                                                                                                                                            
    "sap/m/Button",                                                                                                                                                                                                                                            
    "sap/m/Label",                                                                                                                                                                                                                                             
    "sap/m/Input",                                                                                                                                                                                                                                             
    "sap/m/DatePicker",                                                                                                                                                                                                                                        
    "sap/m/VBox",                                                                                                                                                                                                                                              
    "sap/m/SelectDialog",                                                                                                                                                                                                                                      
    "sap/m/StandardListItem"                                                                                                                                                                                                                                   
], (Controller, JSONModel, Filter, FilterOperator, Sorter, MessageToast, MessageBox, Dialog, Button, Label, Input, DatePicker, VBox, SelectDialog, StandardListItem) => {                                                                                      
    "use strict";                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                               
    return Controller.extend("c1.pp.c1pporder.controller.c1_pp_order", {                                                                                                                                                                                       
        onInit() {                                                                                                                                                                                                                                             
            // view 모델                                                                                                                                                                                                                                         
            // - OData에 저장되는 업무 데이터가 아니라, 화면에서만 필요한 임시 상태를 담는다.                                                                                                                                                                                                
            // - KPI 숫자는 테이블과 별도로 /ProductionOrderMonitor를 읽어서 계산한다.                                                                                                                                                                                           
            // - 이렇게 분리해두면 필터를 바꾸거나 상세 팝업을 열어도 백엔드 엔티티 구조를 건드리지 않는다.                                                                                                                                                                                           
            this.getView().setModel(new JSONModel({                                                                                                                                                                                                            
                kpi: { total: 0, wait: 0, run: 0, done: 0 }                                                                                                                                                                                                    
            }), "view");                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                               
            this.getView().setModel(new JSONModel({                                                                                                                                                                                                            
                busy: false,                                                                                                                                                                                                                                   
                operations: [],                                                                                                                                                                                                                                
                confirmations: [],                                                                                                                                                                                                                             
                components: [],                                                                                                                                                                                                                                
                video: {                                                                                                                                                                                                                                       
                    title: "공정을 선택하세요.",                                                                                                                                                                                                                       
                    available: false                                                                                                                                                                                                                           
                }                                                                                                                                                                                                                                              
            }), "detail");                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
            this.getView().setModel(new JSONModel(this._getInitialCreateOrderData()), "createOrder");                                                                                                                                                          
            // valueHelp 모델                                                                                                                                                                                                                                    
            // - 상단 필터 검색도움과 신규 오더 생성 팝업의 서치헬프가 같이 사용한다.                                                                                                                                                                                                       
            // - /allItems에는 최초 조회한 전체 후보를 보관하고, /items에는 팝업 검색어로 걸러진 목록만 넣는다.                                                                                                                                                                                 
            // - SelectDialog 하나를 재사용하기 때문에, 어떤 필드의 서치헬프인지 별도 변수에 저장해서 선택값을 돌려준다.                                                                                                                                                                              
            this.getView().setModel(new JSONModel({ items: [] }), "valueHelp");                                                                                                                                                                                
                                                                                                                                                                                                                                                               
            // 공정명과 작업영상 파일을 연결하는 매핑이다.                                                                                                                                                                                                                        
            // - 백엔드에서 내려오는 공정명은 공백/기호가 섞일 수 있어서 _normalizeOperationName으로 비교한다.                                                                                                                                                                               
            // - 여기에 keyword만 추가하면 같은 영상 파일을 여러 공정명에서 재사용할 수 있다.                                                                                                                                                                                               
            // - 실제 파일은 webapp/media 아래에 있어야 sap.ui.require.toUrl로 접근 가능하다.                                                                                                                                                                                    
            this._aOperationVideos = [                                                                                                                                                                                                                         
                { keywords: ["프레임조립공정", "프레임조립"], file: "frame-assembly.mp4" },                                                                                                                                                                                
                { keywords: ["전후륜장착", "휠장착"], file: "wheel-install.mp4" },                                                                                                                                                                                     
                { keywords: ["브레이크장착"], file: "brake-install.mp4" },                                                                                                                                                                                           
                { keywords: ["프레임구동부결합", "구동부결합"], file: "frame-drive-combine.mp4" },                                                                                                                                                                          
                { keywords: ["배터리장착"], file: "battery-install.mp4" },                                                                                                                                                                                          
                { keywords: ["제어부설치및배선", "제어부배선"], file: "control-wiring.mp4" },                                                                                                                                                                               
                { keywords: ["핸들안장페달조립", "핸들안장페달"], file: "handle-seat-pedal.mp4" },
                { keywords: ["완제품종합검사", "종합검사"], file: "final-inspection.mp4" },
                { keywords: ["전기자전거최종조립", "최종조립"], file: "ebike-final-assembly.mp4" },
                { keywords: ["전장활성화및세팅", "전장활성화", "세팅"], file: "electrical-activation-setting.mp4" },
                { keywords: ["최종기능주행검사", "기능주행검사"], file: "final-function-road-test.mp4" },
                { keywords: ["포장및출하준비", "출하준비"], file: "packing-shipping-prep.mp4" }
            ];
                                                                                                                                                                                                                                                               
            // 상세 사이드바 비동기 요청 충돌 방지용 번호다.                                                                                                                                                                                                                      
            // 사용자가 A오더를 열자마자 B오더를 누르면 A의 늦은 응답이 B 상세를 덮어쓸 수 있다.                                                                                                                                                                                               
            // 요청을 시작할 때마다 번호를 증가시키고, 응답 시점의 번호가 최신인지 확인해서 오래된 응답을 버린다.                                                                                                                                                                                        
            this._iDetailRequest = 0;                                                                                                                                                                                                                          
            this._fnDrawerKeyDown = (oEvent) => {                                                                                                                                                                                                              
                if (oEvent.key === "Escape") {                                                                                                                                                                                                                 
                    this.onCloseDetail();                                                                                                                                                                                                                      
                }                                                                                                                                                                                                                                              
            };                                                                                                                                                                                                                                                 
            this._fnOutsidePointerDown = (oEvent) => {                                                                                                                                                                                                         
                const oDrawer = this.byId("detailDrawer");                                                                                                                                                                                                     
                const oDrawerDomRef = oDrawer?.getDomRef();                                                                                                                                                                                                    
                                                                                                                                                                                                                                                               
                if (                                                                                                                                                                                                                                           
                    oDrawer?.hasStyleClass("open") &&                                                                                                                                                                                                          
                    oDrawerDomRef &&                                                                                                                                                                                                                           
                    !oDrawerDomRef.contains(oEvent.target)                                                                                                                                                                                                     
                ) {                                                                                                                                                                                                                                            
                    this.onCloseDetail();                                                                                                                                                                                                                      
                }                                                                                                                                                                                                                                              
            };                                                                                                                                                                                                                                                 
            document.addEventListener("keydown", this._fnDrawerKeyDown);                                                                                                                                                                                       
            document.addEventListener("pointerdown", this._fnOutsidePointerDown);                                                                                                                                                                              
            this.getOwnerComponent().getModel().getMetaModel().requestObject("/")                                                                                                                                                                              
                .then(() => this._loadKpis());                                                                                                                                                                                                                 
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        // KPI 카드는 XML에서 sap.m.VBox로 만든 커스텀 카드라 press 이벤트가 없다.                                                                                                                                                                                                 
        // 그래서 렌더링이 끝난 뒤 실제 DOM에 click/keyboard 이벤트를 연결한다.                                                                                                                                                                                                     
        // 화면 재렌더링 시 DOM이 새로 만들어질 수 있으므로 onAfterRendering에서 매번 다시 묶는다.                                                                                                                                                                                         
        onAfterRendering() {                                                                                                                                                                                                                                   
            this._attachKpiCardHandlers();                                                                                                                                                                                                                     
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        onExit() {                                                                                                                                                                                                                                             
            this.getView().$().find(".c1KpiCard").off(".c1Kpi");                                                                                                                                                                                               
            document.removeEventListener("keydown", this._fnDrawerKeyDown);                                                                                                                                                                                    
            document.removeEventListener("pointerdown", this._fnOutsidePointerDown);                                                                                                                                                                           
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        // 상단 검색조건을 OData Filter 배열로 변환해서 테이블 바인딩에 적용한다.                                                                                                                                                                                                       
        // - 생산오더/자재번호/품목명/현재공정은 부분검색(Contains)으로 처리한다.                                                                                                                                                                                                        
        // - 상태는 코드값(WAIT/RUN/DONE)이 정확히 일치해야 하므로 EQ로 처리한다.                                                                                                                                                                                                    
        // - KPI 카드를 눌렀을 때도 statusSelect 값만 바꾸고 이 메소드를 재사용한다.                                                                                                                                                                                                  
        onFilterChange() {                                                                                                                                                                                                                                     
            const aFilters = [];                                                                                                                                                                                                                               
            const sOrderNo = this.byId("orderSearch").getValue().trim();                                                                                                                                                                                       
            const sMaterial = this.byId("materialFilter").getValue().trim();                                                                                                                                                                                   
            const sMaterialText = this.byId("materialTextFilter").getValue().trim();                                                                                                                                                                           
            const sOperation = this.byId("operationFilter").getValue().trim();                                                                                                                                                                                 
            const sStatus = this.byId("statusSelect").getSelectedKey();                                                                                                                                                                                        
                                                                                                                                                                                                                                                               
            if (sOrderNo) {                                                                                                                                                                                                                                    
                aFilters.push(new Filter("OrderNo", FilterOperator.Contains, sOrderNo));                                                                                                                                                                       
            }                                                                                                                                                                                                                                                  
            if (sMaterial) {                                                                                                                                                                                                                                   
                aFilters.push(new Filter("Material", FilterOperator.Contains, sMaterial));                                                                                                                                                                     
            }                                                                                                                                                                                                                                                  
            if (sMaterialText) {                                                                                                                                                                                                                               
                aFilters.push(new Filter("MaterialText", FilterOperator.Contains, sMaterialText));                                                                                                                                                             
            }                                                                                                                                                                                                                                                  
            if (sOperation) {                                                                                                                                                                                                                                  
                aFilters.push(new Filter("CurrentOperationText", FilterOperator.Contains, sOperation));                                                                                                                                                        
            }                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
            if (sStatus !== "ALL") {                                                                                                                                                                                                                           
                aFilters.push(new Filter("CurrentOperationStatus", FilterOperator.EQ, sStatus));                                                                                                                                                               
            }                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
            this.byId("orderTable").getBinding("items").filter(aFilters);                                                                                                                                                                                      
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        onResetFilters() {                                                                                                                                                                                                                                     
            this.byId("orderSearch").setValue("");                                                                                                                                                                                                             
            this.byId("materialFilter").setValue("");                                                                                                                                                                                                          
            this.byId("materialTextFilter").setValue("");                                                                                                                                                                                                      
            this.byId("operationFilter").setValue("");                                                                                                                                                                                                         
            this.byId("statusSelect").setSelectedKey("ALL");                                                                                                                                                                                                   
            this.onFilterChange();                                                                                                                                                                                                                             
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        onKpiPress(oEvent) {                                                                                                                                                                                                                                   
            this._applyKpiFilter(oEvent.getSource().data("status"));                                                                                                                                                                                           
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        // KPI 카드 DOM 이벤트 연결                                                                                                                                                                                                                                   
        // - 카드의 CSS class(c1KpiCardRun/Wait/Done)를 보고 상태값을 알아낸다.                                                                                                                                                                                              
        // - 마우스 클릭뿐 아니라 Enter/Space 키도 처리해서 키보드 접근성을 맞춘다.                                                                                                                                                                                                     
        // - .off(".c1Kpi")로 이전 이벤트를 먼저 제거하므로 재렌더링 후 중복 실행되지 않는다.                                                                                                                                                                                              
        _attachKpiCardHandlers() {                                                                                                                                                                                                                             
            this.getView().$().find(".c1KpiCard")                                                                                                                                                                                                              
                .off(".c1Kpi")                                                                                                                                                                                                                                 
                .attr("role", "button")                                                                                                                                                                                                                        
                .attr("tabindex", "0")                                                                                                                                                                                                                         
                .on("click.c1Kpi", (oEvent) => {                                                                                                                                                                                                               
                    this._applyKpiFilter(this._getKpiStatusFromCard(oEvent.currentTarget));                                                                                                                                                                    
                })                                                                                                                                                                                                                                             
                .on("keydown.c1Kpi", (oEvent) => {                                                                                                                                                                                                             
                    if (oEvent.key === "Enter" || oEvent.key === " ") {                                                                                                                                                                                        
                        oEvent.preventDefault();                                                                                                                                                                                                               
                        this._applyKpiFilter(this._getKpiStatusFromCard(oEvent.currentTarget));                                                                                                                                                                
                    }                                                                                                                                                                                                                                          
                });                                                                                                                                                                                                                                            
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        // XML의 카드 class만 보고 statusSelect의 key 값으로 변환한다.                                                                                                                                                                                                       
        _getKpiStatusFromCard(oCard) {                                                                                                                                                                                                                         
            if (oCard.classList.contains("c1KpiCardRun")) {                                                                                                                                                                                                    
                return "RUN";                                                                                                                                                                                                                                  
            }                                                                                                                                                                                                                                                  
            if (oCard.classList.contains("c1KpiCardWait")) {                                                                                                                                                                                                   
                return "WAIT";                                                                                                                                                                                                                                 
            }                                                                                                                                                                                                                                                  
            if (oCard.classList.contains("c1KpiCardDone")) {                                                                                                                                                                                                   
                return "DONE";                                                                                                                                                                                                                                 
            }                                                                                                                                                                                                                                                  
            return "ALL";                                                                                                                                                                                                                                      
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        // KPI 클릭은 상태 Select 값을 바꾼 뒤 기존 필터 로직을 재사용한다.                                                                                                                                                                                                          
        _applyKpiFilter(sStatus) {                                                                                                                                                                                                                             
            if (!sStatus) {                                                                                                                                                                                                                                    
                return;                                                                                                                                                                                                                                        
            }                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
            this.byId("statusSelect").setSelectedKey(sStatus);                                                                                                                                                                                                 
            this.onFilterChange();                                                                                                                                                                                                                             
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        onOrderFilterValueHelp() {                                                                                                                                                                                                                             
            this._openFilterValueHelp("OrderNo");                                                                                                                                                                                                              
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        onMaterialFilterValueHelp() {                                                                                                                                                                                                                          
            this._openFilterValueHelp("Material");                                                                                                                                                                                                             
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        onMaterialTextFilterValueHelp() {                                                                                                                                                                                                                      
            this._openFilterValueHelp("MaterialText");                                                                                                                                                                                                         
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        onOperationFilterValueHelp() {                                                                                                                                                                                                                         
            this._openFilterValueHelp("CurrentOperationText");                                                                                                                                                                                                 
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        // 상단 필터용 서치헬프 열기                                                                                                                                                                                                                                      
        // - 별도 Value Help CDS가 아니라 현재 목록 서비스(/ProductionOrderMonitor)에서 후보 값을 가져온다.                                                                                                                                                                           
        // - 사용자가 이미 입력한 다른 필터 조건은 같이 반영해서, 현재 화면 맥락에 맞는 후보만 보여준다.                                                                                                                                                                                             
        // - 같은 자재/공정이 여러 오더에 반복되므로 _toDistinctValueHelpItems에서 중복을 제거한다.                                                                                                                                                                                      
        // - SelectDialog는 한 번만 만들고 이후에는 제목/데이터만 바꿔 재사용한다.                                                                                                                                                                                                     
        async _openFilterValueHelp(sField) {                                                                                                                                                                                                                   
            const oValueHelpModel = this.getView().getModel("valueHelp");                                                                                                                                                                                      
            const oConfig = this._getFilterValueHelpConfig(sField);                                                                                                                                                                                            
                                                                                                                                                                                                                                                               
            if (!oConfig) {                                                                                                                                                                                                                                    
                return;                                                                                                                                                                                                                                        
            }                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
            oValueHelpModel.setProperty("/allItems", []);                                                                                                                                                                                                      
            oValueHelpModel.setProperty("/items", []);                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
            try {                                                                                                                                                                                                                                              
                const aItems = await oConfig.load();                                                                                                                                                                                                           
                oValueHelpModel.setProperty("/allItems", aItems);                                                                                                                                                                                              
                oValueHelpModel.setProperty("/items", aItems);                                                                                                                                                                                                 
            } catch (oError) {                                                                                                                                                                                                                                 
                MessageBox.error("검색도움 데이터를 불러오지 못했습니다.");                                                                                                                                                                                                     
                return;                                                                                                                                                                                                                                        
            }                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
            if (!this._oFilterValueHelp) {                                                                                                                                                                                                                     
                this._oFilterValueHelp = new SelectDialog({                                                                                                                                                                                                    
                    search: (oEvent) => this._filterValueHelpItems(oEvent.getParameter("value")),                                                                                                                                                              
                    liveChange: (oEvent) => this._filterValueHelpItems(oEvent.getParameter("value")),                                                                                                                                                          
                    confirm: (oEvent) => this._selectFilterValueHelp(oEvent),                                                                                                                                                                                  
                    cancel: () => this._filterValueHelpItems("")                                                                                                                                                                                               
                });                                                                                                                                                                                                                                            
                this._oFilterValueHelp.bindAggregation("items", {                                                                                                                                                                                              
                    path: "valueHelp>/items",                                                                                                                                                                                                                  
                    template: new StandardListItem({                                                                                                                                                                                                           
                        title: "{valueHelp>key}",                                                                                                                                                                                                              
                        description: "{valueHelp>text}"                                                                                                                                                                                                        
                    })                                                                                                                                                                                                                                         
                });                                                                                                                                                                                                                                            
                this.getView().addDependent(this._oFilterValueHelp);                                                                                                                                                                                           
            }                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
            this._sFilterValueHelpField = sField;                                                                                                                                                                                                              
            this._oFilterValueHelp.setTitle(oConfig.title);                                                                                                                                                                                                    
            this._filterValueHelpItems("");                                                                                                                                                                                                                    
            this._oFilterValueHelp.open();                                                                                                                                                                                                                     
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        // 필터 서치헬프 설정표                                                                                                                                                                                                                                         
        // - sField는 백엔드 엔티티의 필드명이고, inputId는 선택값을 넣을 화면 Input ID다.                                                                                                                                                                                            
        // - title은 SelectDialog 제목, textField는 리스트의 보조 설명으로 보여줄 필드다.                                                                                                                                                                                          
        // - 예: Material을 고르면 key=자재번호, text=품목명 형태로 표시한다.                                                                                                                                                                                                     
        // - $select를 걸어서 서치헬프에 필요한 필드만 읽도록 했다.                                                                                                                                                                                                                
        _getFilterValueHelpConfig(sField) {                                                                                                                                                                                                                    
            const mInputByField = {                                                                                                                                                                                                                            
                OrderNo: "orderSearch",                                                                                                                                                                                                                        
                Material: "materialFilter",                                                                                                                                                                                                                    
                MaterialText: "materialTextFilter",                                                                                                                                                                                                            
                CurrentOperationText: "operationFilter"                                                                                                                                                                                                        
            };                                                                                                                                                                                                                                                 
            const mTitleByField = {                                                                                                                                                                                                                            
                OrderNo: "생산오더 선택",                                                                                                                                                                                                                            
                Material: "자재 선택",                                                                                                                                                                                                                             
                MaterialText: "품목명 선택",                                                                                                                                                                                                                        
                CurrentOperationText: "공정 선택"                                                                                                                                                                                                                  
            };                                                                                                                                                                                                                                                 
            const mTextFieldByField = {                                                                                                                                                                                                                        
                OrderNo: "MaterialText",                                                                                                                                                                                                                       
                Material: "MaterialText",                                                                                                                                                                                                                      
                MaterialText: "Material",                                                                                                                                                                                                                      
                CurrentOperationText: "CurrentWorkCenter"                                                                                                                                                                                                      
            };                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                               
            if (!mInputByField[sField]) {                                                                                                                                                                                                                      
                return null;                                                                                                                                                                                                                                   
            }                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
            return {                                                                                                                                                                                                                                           
                inputId: mInputByField[sField],                                                                                                                                                                                                                
                title: mTitleByField[sField],                                                                                                                                                                                                                  
                load: async () => {                                                                                                                                                                                                                            
                    const aRows = await this._requestValueHelpCollection(                                                                                                                                                                                      
                        "/ProductionOrderMonitor",                                                                                                                                                                                                             
                        this._getFilterValueHelpBaseFilters(sField),                                                                                                                                                                                           
                        [new Sorter(sField)],                                                                                                                                                                                                                  
                        `${sField},${mTextFieldByField[sField]}`                                                                                                                                                                                               
                    );                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
                    return this._toDistinctValueHelpItems(aRows, sField, mTextFieldByField[sField]);                                                                                                                                                           
                }                                                                                                                                                                                                                                              
            };                                                                                                                                                                                                                                                 
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        // 서치헬프 후보 목록을 좁히기 위한 기본 필터 생성                                                                                                                                                                                                                         
        // - 예를 들어 자재번호 서치헬프를 열 때 생산오더/품목명/공정/상태 조건은 반영한다.                                                                                                                                                                                                     
        // - 단, 현재 선택하려는 자재번호 조건까지 반영하면 후보가 이미 입력값에 갇혀버릴 수 있어 제외한다.                                                                                                                                                                                            
        // - 이 방식이라 필터 입력 순서와 상관없이 자연스럽게 후보가 줄어든다.                                                                                                                                                                                                             
        _getFilterValueHelpBaseFilters(sField) {                                                                                                                                                                                                               
            const aFilters = [];                                                                                                                                                                                                                               
            const sOrderNo = this.byId("orderSearch").getValue().trim();                                                                                                                                                                                       
            const sMaterial = this.byId("materialFilter").getValue().trim();                                                                                                                                                                                   
            const sMaterialText = this.byId("materialTextFilter").getValue().trim();                                                                                                                                                                           
            const sOperation = this.byId("operationFilter").getValue().trim();                                                                                                                                                                                 
            const sStatus = this.byId("statusSelect").getSelectedKey();                                                                                                                                                                                        
                                                                                                                                                                                                                                                               
            if (sField !== "OrderNo" && sOrderNo) {                                                                                                                                                                                                            
                aFilters.push(new Filter("OrderNo", FilterOperator.Contains, sOrderNo));                                                                                                                                                                       
            }                                                                                                                                                                                                                                                  
            if (sField !== "Material" && sMaterial) {                                                                                                                                                                                                          
                aFilters.push(new Filter("Material", FilterOperator.Contains, sMaterial));                                                                                                                                                                     
            }                                                                                                                                                                                                                                                  
            if (sField !== "MaterialText" && sMaterialText) {                                                                                                                                                                                                  
                aFilters.push(new Filter("MaterialText", FilterOperator.Contains, sMaterialText));                                                                                                                                                             
            }                                                                                                                                                                                                                                                  
            if (sField !== "CurrentOperationText" && sOperation) {                                                                                                                                                                                             
                aFilters.push(new Filter("CurrentOperationText", FilterOperator.Contains, sOperation));                                                                                                                                                        
            }                                                                                                                                                                                                                                                  
            if (sStatus !== "ALL") {                                                                                                                                                                                                                           
                aFilters.push(new Filter("CurrentOperationStatus", FilterOperator.EQ, sStatus));                                                                                                                                                               
            }                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
            return aFilters;                                                                                                                                                                                                                                   
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        _filterValueHelpItems(sValue) {                                                                                                                                                                                                                        
            this._filterValueHelpModelItems("valueHelp", sValue);                                                                                                                                                                                              
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        _selectFilterValueHelp(oEvent) {                                                                                                                                                                                                                       
            const oSelectedItem = oEvent.getParameter("selectedItem");                                                                                                                                                                                         
            const oContext = oSelectedItem?.getBindingContext("valueHelp");                                                                                                                                                                                    
            const oItem = oContext?.getObject();                                                                                                                                                                                                               
            const oConfig = this._getFilterValueHelpConfig(this._sFilterValueHelpField);                                                                                                                                                                       
                                                                                                                                                                                                                                                               
            if (!oItem || !oConfig) {                                                                                                                                                                                                                          
                return;                                                                                                                                                                                                                                        
            }                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
            this.byId(oConfig.inputId).setValue(oItem.key);                                                                                                                                                                                                    
            this._filterValueHelpItems("");                                                                                                                                                                                                                    
            this.onFilterChange();                                                                                                                                                                                                                             
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        onRefresh() {                                                                                                                                                                                                                                          
            const oBinding = this.byId("orderTable").getBinding("items");                                                                                                                                                                                      
            if (oBinding) {                                                                                                                                                                                                                                    
                oBinding.refresh();                                                                                                                                                                                                                            
            }                                                                                                                                                                                                                                                  
            this._loadKpis();                                                                                                                                                                                                                                  
            MessageToast.show("생산오더 데이터를 새로고침했습니다.");                                                                                                                                                                                                          
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        onCreateOrder() {                                                                                                                                                                                                                                      
            this._openCreateOrderDialog();                                                                                                                                                                                                                     
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        onOrderPress(oEvent) {                                                                                                                                                                                                                                 
            const oContext = oEvent.getSource().getBindingContext();                                                                                                                                                                                           
            const oOrder = oContext.getObject();                                                                                                                                                                                                               
                                                                                                                                                                                                                                                               
            this.byId("detailDrawer").setBindingContext(oContext);                                                                                                                                                                                             
            this.byId("detailDrawer").addStyleClass("open");                                                                                                                                                                                                   
            this._loadOrderDetails(                                                                                                                                                                                                                            
                oOrder.OrderNo,                                                                                                                                                                                                                                
                oOrder.OrderItemNo,                                                                                                                                                                                                                            
                oOrder.CurrentOperationNo                                                                                                                                                                                                                      
            );                                                                                                                                                                                                                                                 
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        onCloseDetail() {                                                                                                                                                                                                                                      
            this._iDetailRequest += 1;                                                                                                                                                                                                                         
            const oVideo = this._getWorkVideoDomRef();                                                                                                                                                                                                         
            if (oVideo) {                                                                                                                                                                                                                                      
                oVideo.pause();                                                                                                                                                                                                                                
            }                                                                                                                                                                                                                                                  
            this.byId("detailDrawer").removeStyleClass("open");                                                                                                                                                                                                
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        onOperationPress(oEvent) {                                                                                                                                                                                                                             
            const oOperation = oEvent.getSource().getBindingContext("detail").getObject();                                                                                                                                                                     
            this._showOperationVideo(oOperation);                                                                                                                                                                                                              
            this.byId("detailTabs").setSelectedKey("video");                                                                                                                                                                                                   
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        // KPI 숫자 계산                                                                                                                                                                                                                                           
        // - 테이블 바인딩의 현재 표시 건수가 아니라, 전체 /ProductionOrderMonitor 데이터를 기준으로 상태별 건수를 계산한다.                                                                                                                                                                        
        // - CurrentOperationStatus만 $select 해서 네트워크 부담을 줄인다.                                                                                                                                                                                                  
        // - 상태 코드가 WAIT/RUN/DONE인 건만 각각 카운트하고 전체는 조회 건수로 잡는다.                                                                                                                                                                                                 
        async _loadKpis() {                                                                                                                                                                                                                                    
            const oBinding = this.getOwnerComponent().getModel().bindList(                                                                                                                                                                                     
                "/ProductionOrderMonitor",                                                                                                                                                                                                                     
                undefined,                                                                                                                                                                                                                                     
                undefined,                                                                                                                                                                                                                                     
                undefined,                                                                                                                                                                                                                                     
                { $select: "CurrentOperationStatus" }                                                                                                                                                                                                          
            );                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                               
            try {                                                                                                                                                                                                                                              
                const aContexts = await oBinding.requestContexts(0, 5000);                                                                                                                                                                                     
                const oKpi = { total: aContexts.length, wait: 0, run: 0, done: 0 };                                                                                                                                                                            
                                                                                                                                                                                                                                                               
                aContexts.forEach((oContext) => {                                                                                                                                                                                                              
                    const sStatus = oContext.getProperty("CurrentOperationStatus");                                                                                                                                                                            
                    if (sStatus === "WAIT") {                                                                                                                                                                                                                  
                        oKpi.wait += 1;                                                                                                                                                                                                                        
                    } else if (sStatus === "RUN") {                                                                                                                                                                                                            
                        oKpi.run += 1;                                                                                                                                                                                                                         
                    } else if (sStatus === "DONE") {                                                                                                                                                                                                           
                        oKpi.done += 1;                                                                                                                                                                                                                        
                    }                                                                                                                                                                                                                                          
                });                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                               
                this.getView().getModel("view").setProperty("/kpi", oKpi);                                                                                                                                                                                     
            } catch (oError) {                                                                                                                                                                                                                                 
                MessageToast.show("KPI 데이터를 불러오지 못했습니다.");                                                                                                                                                                                                     
            } finally {                                                                                                                                                                                                                                        
                oBinding.destroy();                                                                                                                                                                                                                            
            }                                                                                                                                                                                                                                                  
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        // 오른쪽 생산오더 상세 로딩                                                                                                                                                                                                                                      
        // - 한 오더의 공정 진행, 실적 이력, 투입 자재를 각각 다른 엔티티에서 동시에 읽는다.                                                                                                                                                                                                   
        // - Promise.all을 쓰는 이유는 세 목록이 서로 기다릴 필요가 없고, 동시에 읽는 편이 사이드바 표시가 빠르기 때문이다.                                                                                                                                                                             
        // - _iDetailRequest 값으로 오래된 응답을 버려서 빠르게 여러 행을 클릭해도 상세 내용이 섞이지 않게 한다.                                                                                                                                                                                  
        async _loadOrderDetails(sOrderNo, sOrderItemNo, sCurrentOperationNo) {                                                                                                                                                                                 
            const iRequest = ++this._iDetailRequest;                                                                                                                                                                                                           
            const oDetailModel = this.getView().getModel("detail");                                                                                                                                                                                            
            const aOrderFilters = [                                                                                                                                                                                                                            
                new Filter("OrderNo", FilterOperator.EQ, sOrderNo),                                                                                                                                                                                            
                new Filter("OrderItemNo", FilterOperator.EQ, sOrderItemNo)                                                                                                                                                                                     
            ];                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                               
            oDetailModel.setProperty("/busy", true);                                                                                                                                                                                                           
            oDetailModel.setProperty("/operations", []);                                                                                                                                                                                                       
            oDetailModel.setProperty("/confirmations", []);                                                                                                                                                                                                    
            oDetailModel.setProperty("/components", []);                                                                                                                                                                                                       
                                                                                                                                                                                                                                                               
            try {                                                                                                                                                                                                                                              
                const [aOperations, aConfirmations, aComponents] = await Promise.all([                                                                                                                                                                         
                    this._requestCollection("/ProductionOrderOperations", aOrderFilters, [new Sorter("OperationNo")]),                                                                                                                                         
                    this._requestCollection("/OperationConfirmations", aOrderFilters, [new Sorter("PostingDate", true)]),                                                                                                                                      
                    this._requestCollection("/OrderComponents", aOrderFilters, [new Sorter("ComponentItemNo")])                                                                                                                                                
                ]);                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                               
                if (iRequest !== this._iDetailRequest) {                                                                                                                                                                                                       
                    return;                                                                                                                                                                                                                                    
                }                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                               
                oDetailModel.setProperty("/operations", aOperations);                                                                                                                                                                                          
                oDetailModel.setProperty("/confirmations", aConfirmations);                                                                                                                                                                                    
                oDetailModel.setProperty("/components", aComponents);                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
                const oCurrentOperation = aOperations.find(                                                                                                                                                                                                    
                    (oOperation) => oOperation.OperationNo === sCurrentOperationNo                                                                                                                                                                             
                ) || aOperations[0];                                                                                                                                                                                                                           
                this._showOperationVideo(oCurrentOperation);                                                                                                                                                                                                   
            } catch (oError) {                                                                                                                                                                                                                                 
                if (iRequest === this._iDetailRequest) {                                                                                                                                                                                                       
                    MessageToast.show("생산오더 상세 데이터를 불러오지 못했습니다.");                                                                                                                                                                                             
                }                                                                                                                                                                                                                                              
            } finally {                                                                                                                                                                                                                                        
                if (iRequest === this._iDetailRequest) {                                                                                                                                                                                                       
                    oDetailModel.setProperty("/busy", false);                                                                                                                                                                                                  
                }                                                                                                                                                                                                                                              
            }                                                                                                                                                                                                                                                  
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        // 공정별 작업 영상 표시                                                                                                                                                                                                                                        
        // - 선택한 공정명을 정규화한 뒤 _aOperationVideos의 keyword와 비교한다.                                                                                                                                                                                                 
        // - 일치하는 영상이 없으면 MessageStrip만 보이고, core:HTML의 video 내용은 비운다.                                                                                                                                                                                         
        // - 영상이 있으면 webapp/media의 mp4 파일을 HTML video 태그로 넣는다.                                                                                                                                                                                                 
        // - 자동재생은 Chrome 정책상 muted가 필요해서 muted/autoplay/loop를 같이 지정한다.                                                                                                                                                                                        
        // - 일부 브라우저에서 native video controls의 seek 클릭이 UI5 레이어 안에서 불안정할 수 있어                                                                                                                                                                                   
        //   렌더 후 _enhanceWorkVideo에서 하단 재생바 영역 클릭을 직접 currentTime으로 보정한다.                                                                                                                                                                                     
        _showOperationVideo(oOperation) {                                                                                                                                                                                                                      
            const oDetailModel = this.getView().getModel("detail");                                                                                                                                                                                            
            const sOperationText = oOperation?.OperationText || "";                                                                                                                                                                                            
            const sNormalizedText = this._normalizeOperationName(sOperationText);                                                                                                                                                                              
            const oVideoConfig = this._aOperationVideos.find((oConfig) =>                                                                                                                                                                                      
                oConfig.keywords.some((sKeyword) =>                                                                                                                                                                                                            
                    sNormalizedText.includes(this._normalizeOperationName(sKeyword))                                                                                                                                                                           
                )                                                                                                                                                                                                                                              
            );                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                               
            oDetailModel.setProperty(                                                                                                                                                                                                                          
                "/video/title",                                                                                                                                                                                                                                
                oOperation                                                                                                                                                                                                                                     
                    ? `${oOperation.OperationNo} · ${sOperationText}`                                                                                                                                                                                          
                    : "공정을 선택하세요."                                                                                                                                                                                                                             
            );                                                                                                                                                                                                                                                 
            oDetailModel.setProperty("/video/available", Boolean(oVideoConfig));                                                                                                                                                                               
                                                                                                                                                                                                                                                               
            if (!oVideoConfig) {                                                                                                                                                                                                                               
                this.byId("workVideo").setContent("");                                                                                                                                                                                                         
                return;                                                                                                                                                                                                                                        
            }                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
            const sVideoUrl = sap.ui.require.toUrl(                                                                                                                                                                                                            
                `c1/pp/c1pporder/media/${oVideoConfig.file}`                                                                                                                                                                                                   
            );                                                                                                                                                                                                                                                 
            this.byId("workVideo").setContent(`                                                                                                                                                                                                                
                <video                                                                                                                                                                                                                                         
                    autoplay                                                                                                                                                                                                                                   
                    controls                                                                                                                                                                                                                                   
                    loop                                                                                                                                                                                                                                       
                    muted                                                                                                                                                                                                                                      
                    playsinline                                                                                                                                                                                                                                
                    preload="auto"                                                                                                                                                                                                                             
                    aria-label="${this._escapeHtml(sOperationText)} 작업 영상"                                                                                                                                                                                     
                    class="c1WorkVideo">                                                                                                                                                                                                                       
                    <source src="${sVideoUrl}" type="video/mp4">                                                                                                                                                                                               
                    이 브라우저에서는 영상을 재생할 수 없습니다.                                                                                                                                                                                                                  
                </video>                                                                                                                                                                                                                                       
            `);                                                                                                                                                                                                                                                
            this._scheduleEnhanceWorkVideo();                                                                                                                                                                                                                  
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        // core:HTML은 setContent 직후 DOM이 아직 교체 중일 수 있다.                                                                                                                                                                                                        
        // 그래서 짧게 여러 번 확인해서 실제 video 태그가 생긴 시점에 보강 로직을 적용한다.                                                                                                                                                                                                   
        _scheduleEnhanceWorkVideo() {                                                                                                                                                                                                                          
            [0, 50, 150, 300, 600].forEach((iDelay) => {                                                                                                                                                                                                       
                window.setTimeout(() => this._enhanceWorkVideo(), iDelay);                                                                                                                                                                                     
            });                                                                                                                                                                                                                                                
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        // 작업 영상 자동재생/반복재생 및 seek 클릭 보강                                                                                                                                                                                                                        
        // - muted 상태의 play()는 대부분의 브라우저 자동재생 정책을 통과한다.                                                                                                                                                                                                        
        // - 영상이 끝나면 loop 속성으로 자동 반복된다.                                                                                                                                                                                                                        
        // - native controls의 진행바 클릭이 먹지 않는 환경을 대비해, 하단 컨트롤 영역 클릭을 직접 계산한다.                                                                                                                                                                                    
        // - 왼쪽 play 버튼 영역은 재생/일시정지 토글, 가운데 진행바 영역은 클릭 위치만큼 currentTime 이동으로 처리한다.                                                                                                                                                                             
        _enhanceWorkVideo() {                                                                                                                                                                                                                                  
            const oVideo = this._getWorkVideoDomRef();                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
            if (!oVideo || oVideo.dataset.c1Enhanced === "true") {                                                                                                                                                                                             
                return;                                                                                                                                                                                                                                        
            }                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
            oVideo.dataset.c1Enhanced = "true";                                                                                                                                                                                                                
            oVideo.muted = true;                                                                                                                                                                                                                               
            oVideo.loop = true;                                                                                                                                                                                                                                
            oVideo.autoplay = true;                                                                                                                                                                                                                            
            oVideo.preload = "auto";                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                               
            const fnPlay = () => {                                                                                                                                                                                                                             
                const oPlayPromise = oVideo.play();                                                                                                                                                                                                            
                if (oPlayPromise?.catch) {                                                                                                                                                                                                                     
                    oPlayPromise.catch(() => {                                                                                                                                                                                                                 
                        // 브라우저 정책이나 사용자의 설정으로 자동재생이 막히면 controls는 그대로 남긴다.                                                                                                                                                                                    
                    });                                                                                                                                                                                                                                        
                }                                                                                                                                                                                                                                              
            };                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                               
            oVideo.addEventListener("loadedmetadata", fnPlay, { once: true });                                                                                                                                                                                 
            oVideo.addEventListener("canplay", fnPlay, { once: true });                                                                                                                                                                                        
            fnPlay();                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
            oVideo.addEventListener("pointerdown", (oEvent) => {                                                                                                                                                                                               
                const oRect = oVideo.getBoundingClientRect();                                                                                                                                                                                                  
                const iX = oEvent.clientX - oRect.left;                                                                                                                                                                                                        
                const iY = oEvent.clientY - oRect.top;                                                                                                                                                                                                         
                const iControlHeight = 48;                                                                                                                                                                                                                     
                const iProgressLeft = 72;                                                                                                                                                                                                                      
                const iProgressRight = 120;                                                                                                                                                                                                                    
                const bControlArea = iY >= oRect.height - iControlHeight;                                                                                                                                                                                      
                const bPlayArea = bControlArea && iX <= iProgressLeft;                                                                                                                                                                                         
                const bProgressArea = bControlArea &&                                                                                                                                                                                                          
                    iX > iProgressLeft &&                                                                                                                                                                                                                      
                    iX < oRect.width - iProgressRight;                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
                if (bPlayArea) {                                                                                                                                                                                                                               
                    oEvent.preventDefault();                                                                                                                                                                                                                   
                    oEvent.stopPropagation();                                                                                                                                                                                                                  
                    if (oVideo.paused) {                                                                                                                                                                                                                       
                        fnPlay();                                                                                                                                                                                                                              
                    } else {                                                                                                                                                                                                                                   
                        oVideo.pause();                                                                                                                                                                                                                        
                    }                                                                                                                                                                                                                                          
                    return;                                                                                                                                                                                                                                    
                }                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                               
                if (bProgressArea && Number.isFinite(oVideo.duration) && oVideo.duration > 0) {                                                                                                                                                                
                    const fRatio = Math.max(                                                                                                                                                                                                                   
                        0,                                                                                                                                                                                                                                     
                        Math.min(1, (iX - iProgressLeft) / (oRect.width - iProgressLeft - iProgressRight))                                                                                                                                                     
                    );                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
                    oEvent.preventDefault();                                                                                                                                                                                                                   
                    oEvent.stopPropagation();                                                                                                                                                                                                                  
                    oVideo.currentTime = oVideo.duration * fRatio;                                                                                                                                                                                             
                    fnPlay();                                                                                                                                                                                                                                  
                }                                                                                                                                                                                                                                              
            });                                                                                                                                                                                                                                                
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        // sap.ui.core.HTML은 렌더 결과에 따라 control DOM 자체가 video가 되기도 하고,                                                                                                                                                                                          
        // wrapper 아래에 video가 생기기도 한다. 두 경우를 모두 처리해서 영상 DOM을 안정적으로 찾는다.                                                                                                                                                                                        
        _getWorkVideoDomRef() {                                                                                                                                                                                                                                
            const oDomRef = this.byId("workVideo")?.getDomRef();                                                                                                                                                                                               
                                                                                                                                                                                                                                                               
            if (!oDomRef) {                                                                                                                                                                                                                                    
                return null;                                                                                                                                                                                                                                   
            }                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
            if (oDomRef.tagName === "VIDEO") {                                                                                                                                                                                                                 
                return oDomRef;                                                                                                                                                                                                                                
            }                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
            return oDomRef.querySelector("video");                                                                                                                                                                                                             
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        _escapeHtml(sValue) {                                                                                                                                                                                                                                  
            return String(sValue || "")                                                                                                                                                                                                                        
                .replace(/&/g, "&amp;")                                                                                                                                                                                                                        
                .replace(/</g, "&lt;")                                                                                                                                                                                                                         
                .replace(/>/g, "&gt;")                                                                                                                                                                                                                         
                .replace(/"/g, "&quot;")                                                                                                                                                                                                                       
                .replace(/'/g, "&#39;");                                                                                                                                                                                                                       
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        _normalizeOperationName(sName) {                                                                                                                                                                                                                       
            return String(sName || "")                                                                                                                                                                                                                         
                .replace(/[\s+\-_/()]/g, "")                                                                                                                                                                                                                   
                .toLowerCase();                                                                                                                                                                                                                                
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        async _requestCollection(sPath, aFilters, aSorters) {                                                                                                                                                                                                  
            const oBinding = this.getOwnerComponent().getModel().bindList(                                                                                                                                                                                     
                sPath,                                                                                                                                                                                                                                         
                undefined,                                                                                                                                                                                                                                     
                aSorters,                                                                                                                                                                                                                                      
                aFilters                                                                                                                                                                                                                                       
            );                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                               
            try {                                                                                                                                                                                                                                              
                const aContexts = await oBinding.requestContexts(0, 500);                                                                                                                                                                                      
                return aContexts.map((oContext) => ({ ...oContext.getObject() }));                                                                                                                                                                             
            } finally {                                                                                                                                                                                                                                        
                oBinding.destroy();                                                                                                                                                                                                                            
            }                                                                                                                                                                                                                                                  
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        // 신규 생산오더 팝업의 초기값                                                                                                                                                                                                                                     
        // - Plant/StorageLocation/BaseUnit은 우리 프로젝트에서 자주 쓰는 기본값을 미리 넣는다.                                                                                                                                                                                      
        // - BaseUnit은 자재 선택 시 자재마스터 기준값으로 갱신하고, 팝업에서는 직접 수정하지 못하게 막아둔다.                                                                                                                                                                                       
        // - 팝업을 다시 열 때 이전 입력값이 남지 않도록 이 메소드로 모델을 매번 초기화한다.                                                                                                                                                                                                    
        _getInitialCreateOrderData() {                                                                                                                                                                                                                         
            return {                                                                                                                                                                                                                                           
                busy: false,                                                                                                                                                                                                                                   
                Plant: "TS00",                                                                                                                                                                                                                                 
                Material: "",                                                                                                                                                                                                                                  
                BasicStartDate: "",                                                                                                                                                                                                                            
                BasicEndDate: "",                                                                                                                                                                                                                              
                OrderQty: "",                                                                                                                                                                                                                                  
                BaseUnit: "EA",                                                                                                                                                                                                                                
                StorageLocation: "SL30"                                                                                                                                                                                                                        
            };                                                                                                                                                                                                                                                 
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        // 신규 생산오더 생성 팝업 구성                                                                                                                                                                                                                                    
        // - XML에 고정하지 않고 JS에서 Dialog를 만든 이유는 이 화면에서만 쓰는 단순 입력 팝업이기 때문이다.                                                                                                                                                                                      
        // - 최초 한 번만 생성하고 이후에는 같은 Dialog를 재사용한다.                                                                                                                                                                                                               
        // - 생성 버튼을 누르면 _submitCreateOrder에서 RAP action CreateProductionOrder를 호출한다.                                                                                                                                                                           
        _openCreateOrderDialog() {                                                                                                                                                                                                                             
            this.getView().getModel("createOrder").setData(this._getInitialCreateOrderData());                                                                                                                                                                 
                                                                                                                                                                                                                                                               
            if (!this._oCreateOrderDialog) {                                                                                                                                                                                                                   
                this._oCreateOrderDialog = new Dialog({                                                                                                                                                                                                        
                    title: "신규 생산오더 생성",                                                                                                                                                                                                                       
                    contentWidth: "32rem",                                                                                                                                                                                                                     
                    busy: "{createOrder>/busy}",                                                                                                                                                                                                               
                    busyIndicatorDelay: 0,                                                                                                                                                                                                                     
                    content: [                                                                                                                                                                                                                                 
                        new VBox({                                                                                                                                                                                                                             
                            class: "c1CreateOrderDialog sapUiSmallMargin",                                                                                                                                                                                     
                            items: [                                                                                                                                                                                                                           
                                new Label({ text: "플랜트", required: true }),                                                                                                                                                                                    
                                new Input({                                                                                                                                                                                                                    
                                    value: "{createOrder>/Plant}",                                                                                                                                                                                             
                                    maxLength: 4,                                                                                                                                                                                                              
                                    placeholder: "예: TS00",                                                                                                                                                                                                    
                                    showValueHelp: true,                                                                                                                                                                                                       
                                    valueHelpOnly: false,                                                                                                                                                                                                      
                                    valueHelpRequest: () => this._openCreateOrderValueHelp("Plant")                                                                                                                                                            
                                }),                                                                                                                                                                                                                            
                                new Label({ text: "자재", required: true }),                                                                                                                                                                                     
                                new Input({                                                                                                                                                                                                                    
                                    value: "{createOrder>/Material}",                                                                                                                                                                                          
                                    placeholder: "생산할 자재 번호",                                                                                                                                                                                                  
                                    showValueHelp: true,                                                                                                                                                                                                       
                                    valueHelpOnly: false,                                                                                                                                                                                                      
                                    valueHelpRequest: () => this._openCreateOrderValueHelp("Material")                                                                                                                                                         
                                }),                                                                                                                                                                                                                            
                                new Label({ text: "기본 시작일", required: true }),                                                                                                                                                                                 
                                new DatePicker({                                                                                                                                                                                                               
                                    value: "{createOrder>/BasicStartDate}",                                                                                                                                                                                    
                                    valueFormat: "yyyy-MM-dd",                                                                                                                                                                                                 
                                    displayFormat: "yyyy-MM-dd",                                                                                                                                                                                               
                                    placeholder: "YYYY-MM-DD"                                                                                                                                                                                                  
                                }),                                                                                                                                                                                                                            
                                new Label({ text: "기본 종료일", required: true }),                                                                                                                                                                                 
                                new DatePicker({                                                                                                                                                                                                               
                                    value: "{createOrder>/BasicEndDate}",                                                                                                                                                                                      
                                    valueFormat: "yyyy-MM-dd",                                                                                                                                                                                                 
                                    displayFormat: "yyyy-MM-dd",                                                                                                                                                                                               
                                    placeholder: "YYYY-MM-DD"                                                                                                                                                                                                  
                                }),                                                                                                                                                                                                                            
                                new Label({ text: "생산수량", required: true }),                                                                                                                                                                                   
                                new Input({                                                                                                                                                                                                                    
                                    value: "{createOrder>/OrderQty}",                                                                                                                                                                                          
                                    type: "Number",                                                                                                                                                                                                            
                                    placeholder: "0보다 큰 수량"                                                                                                                                                                                                    
                                }),                                                                                                                                                                                                                            
                                new Label({ text: "기본단위" }),                                                                                                                                                                                                   
                                new Input({                                                                                                                                                                                                                    
                                    value: "{createOrder>/BaseUnit}",                                                                                                                                                                                          
                                    editable: false                                                                                                                                                                                                            
                                }),                                                                                                                                                                                                                            
                                new Label({ text: "저장위치" }),                                                                                                                                                                                                   
                                new Input({                                                                                                                                                                                                                    
                                    value: "{createOrder>/StorageLocation}",                                                                                                                                                                                   
                                    maxLength: 4,                                                                                                                                                                                                              
                                    placeholder: "예: SL30"                                                                                                                                                                                                     
                                })                                                                                                                                                                                                                             
                            ]                                                                                                                                                                                                                                  
                        })                                                                                                                                                                                                                                     
                    ],                                                                                                                                                                                                                                         
                    beginButton: new Button({                                                                                                                                                                                                                  
                        text: "생성",                                                                                                                                                                                                                            
                        type: "Emphasized",                                                                                                                                                                                                                    
                        press: () => this._submitCreateOrder()                                                                                                                                                                                                 
                    }),                                                                                                                                                                                                                                        
                    endButton: new Button({                                                                                                                                                                                                                    
                        text: "취소",                                                                                                                                                                                                                            
                        press: () => this._oCreateOrderDialog.close()                                                                                                                                                                                          
                    })                                                                                                                                                                                                                                         
                });                                                                                                                                                                                                                                            
                this.getView().addDependent(this._oCreateOrderDialog);                                                                                                                                                                                         
            }                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
            this._oCreateOrderDialog.open();                                                                                                                                                                                                                   
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        // 신규 생산오더 팝업용 서치헬프                                                                                                                                                                                                                                    
        // - 상단 필터 서치헬프와 같은 valueHelp 모델/SelectDialog 패턴을 쓴다.                                                                                                                                                                                                  
        // - Plant는 플랜트 후보를, Material은 선택된 Plant 기준의 자재 후보를 보여준다.                                                                                                                                                                                              
        // - busy는 createOrder 모델에 걸어서 팝업 안에서 로딩 상태를 표시한다.                                                                                                                                                                                                     
        async _openCreateOrderValueHelp(sField) {                                                                                                                                                                                                              
            const oCreateModel = this.getView().getModel("createOrder");                                                                                                                                                                                       
            const oValueHelpModel = this.getView().getModel("valueHelp");                                                                                                                                                                                      
            const oConfig = this._getCreateOrderValueHelpConfig(sField);                                                                                                                                                                                       
                                                                                                                                                                                                                                                               
            if (!oConfig) {                                                                                                                                                                                                                                    
                return;                                                                                                                                                                                                                                        
            }                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
            oValueHelpModel.setProperty("/allItems", []);                                                                                                                                                                                                      
            oValueHelpModel.setProperty("/items", []);                                                                                                                                                                                                         
            oCreateModel.setProperty("/busy", true);                                                                                                                                                                                                           
                                                                                                                                                                                                                                                               
            try {                                                                                                                                                                                                                                              
                const aItems = await oConfig.load();                                                                                                                                                                                                           
                oValueHelpModel.setProperty("/allItems", aItems);                                                                                                                                                                                              
                oValueHelpModel.setProperty("/items", aItems);                                                                                                                                                                                                 
            } catch (oError) {                                                                                                                                                                                                                                 
                MessageBox.error("서치헬프 데이터를 불러오지 못했습니다.");                                                                                                                                                                                                     
                return;                                                                                                                                                                                                                                        
            } finally {                                                                                                                                                                                                                                        
                oCreateModel.setProperty("/busy", false);                                                                                                                                                                                                      
            }                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
            if (!this._oCreateOrderValueHelp) {                                                                                                                                                                                                                
                this._oCreateOrderValueHelp = new SelectDialog({                                                                                                                                                                                               
                    search: (oEvent) => this._filterCreateOrderValueHelp(oEvent.getParameter("value")),                                                                                                                                                        
                    liveChange: (oEvent) => this._filterCreateOrderValueHelp(oEvent.getParameter("value")),                                                                                                                                                    
                    confirm: (oEvent) => this._selectCreateOrderValueHelp(oEvent),                                                                                                                                                                             
                    cancel: () => this._filterCreateOrderValueHelp("")                                                                                                                                                                                         
                });                                                                                                                                                                                                                                            
                this._oCreateOrderValueHelp.bindAggregation("items", {                                                                                                                                                                                         
                    path: "valueHelp>/items",                                                                                                                                                                                                                  
                    template: new StandardListItem({                                                                                                                                                                                                           
                        title: "{valueHelp>key}",                                                                                                                                                                                                              
                        description: "{valueHelp>text}"                                                                                                                                                                                                        
                    })                                                                                                                                                                                                                                         
                });                                                                                                                                                                                                                                            
                this.getView().addDependent(this._oCreateOrderValueHelp);                                                                                                                                                                                      
            }                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
            this._sCreateOrderValueHelpField = sField;                                                                                                                                                                                                         
            this._oCreateOrderValueHelp.setTitle(oConfig.title);                                                                                                                                                                                               
            this._filterCreateOrderValueHelp("");                                                                                                                                                                                                              
            this._oCreateOrderValueHelp.open();                                                                                                                                                                                                                
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        // 신규 오더 입력 팝업의 서치헬프 설정                                                                                                                                                                                                                                
        // - Plant 후보는 플랜트 Value Help(/Plants)에서 전체 후보를 가져온다.                                                                                                                                                                                                  
        // - Material 후보는 자재마스터 Value Help(/Materials)에서 전체 후보를 가져온다.                                                                                                                                                                                          
        _getCreateOrderValueHelpConfig(sField) {                                                                                                                                                                                                               
            if (sField === "Plant") {                                                                                                                                                                                                                          
                return {                                                                                                                                                                                                                                       
                    title: "플랜트 선택",                                                                                                                                                                                                                           
                    load: async () => {                                                                                                                                                                                                                        
                        const aRows = await this._requestValueHelpCollection(                                                                                                                                                                                  
                            "/Plants",                                                                                                                                                                                                                         
                            [],                                                                                                                                                                                                                                
                            [new Sorter("Plant")],                                                                                                                                                                                                             
                            "Plant,PlantName"                                                                                                                                                                                                                  
                        );                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
                        return this._toDistinctValueHelpItems(aRows, "Plant", "PlantName");                                                                                                                                                                    
                    }                                                                                                                                                                                                                                          
                };                                                                                                                                                                                                                                             
            }                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
            if (sField === "Material") {                                                                                                                                                                                                                       
                return {                                                                                                                                                                                                                                       
                    title: "자재 선택",                                                                                                                                                                                                                            
                    load: async () => {                                                                                                                                                                                                                        
                        const aRows = await this._requestValueHelpCollection(                                                                                                                                                                                  
                            "/Materials",                                                                                                                                                                                                                      
                            [],                                                                                                                                                                                                                                
                            [new Sorter("Material")],                                                                                                                                                                                                          
                            "Material,MaterialText,MaterialType,BaseUnit"                                                                                                                                                                                      
                        );                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
                        return this._toDistinctValueHelpItems(aRows, "Material", "MaterialText");                                                                                                                                                              
                    }                                                                                                                                                                                                                                          
                };                                                                                                                                                                                                                                             
            }                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
            return null;                                                                                                                                                                                                                                       
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        _filterCreateOrderValueHelp(sValue) {                                                                                                                                                                                                                  
            this._filterValueHelpModelItems("valueHelp", sValue);                                                                                                                                                                                              
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        _filterValueHelpModelItems(sModelName, sValue) {                                                                                                                                                                                                       
            const oValueHelpModel = this.getView().getModel(sModelName);                                                                                                                                                                                       
                                                                                                                                                                                                                                                               
            if (!oValueHelpModel) {                                                                                                                                                                                                                            
                return;                                                                                                                                                                                                                                        
            }                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
            const sNeedle = String(sValue || "").trim().toLowerCase();                                                                                                                                                                                         
            const aItems = oValueHelpModel.getProperty("/allItems") || [];                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
            oValueHelpModel.setProperty(                                                                                                                                                                                                                       
                "/items",                                                                                                                                                                                                                                      
                sNeedle                                                                                                                                                                                                                                        
                    ? aItems.filter((oItem) =>                                                                                                                                                                                                                 
                        String(oItem.key || "").toLowerCase().includes(sNeedle) ||                                                                                                                                                                             
                        String(oItem.text || "").toLowerCase().includes(sNeedle)                                                                                                                                                                               
                    )                                                                                                                                                                                                                                          
                    : aItems                                                                                                                                                                                                                                   
            );                                                                                                                                                                                                                                                 
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        _selectCreateOrderValueHelp(oEvent) {                                                                                                                                                                                                                  
            const oSelectedItem = oEvent.getParameter("selectedItem");                                                                                                                                                                                         
            const oContext = oSelectedItem?.getBindingContext("valueHelp");                                                                                                                                                                                    
            const oItem = oContext?.getObject();                                                                                                                                                                                                               
                                                                                                                                                                                                                                                               
            if (!oItem || !this._sCreateOrderValueHelpField) {                                                                                                                                                                                                 
                return;                                                                                                                                                                                                                                        
            }                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
            const oCreateModel = this.getView().getModel("createOrder");                                                                                                                                                                                       
            oCreateModel.setProperty(`/${this._sCreateOrderValueHelpField}`, oItem.key);                                                                                                                                                                       
                                                                                                                                                                                                                                                               
            if (this._sCreateOrderValueHelpField === "Material") {                                                                                                                                                                                             
                oCreateModel.setProperty("/StorageLocation", this._getDefaultStorageLocation(oItem.materialType));                                                                                                                                             
                                                                                                                                                                                                                                                               
                if (oItem.baseUnit) {                                                                                                                                                                                                                          
                    oCreateModel.setProperty("/BaseUnit", oItem.baseUnit);                                                                                                                                                                                     
                }                                                                                                                                                                                                                                              
            }                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
            this._filterCreateOrderValueHelp("");                                                                                                                                                                                                              
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        _getDefaultStorageLocation(sMaterialType) {                                                                                                                                                                                                            
            const mStorageLocationByMaterialType = {                                                                                                                                                                                                           
                FERT: "SL30",                                                                                                                                                                                                                                  
                HALB: "SL20"                                                                                                                                                                                                                                   
            };                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                               
            return mStorageLocationByMaterialType[String(sMaterialType || "").trim()] || "SL30";                                                                                                                                                               
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        async _requestValueHelpCollection(sPath, aFilters, aSorters, sSelect) {                                                                                                                                                                                
            const oBinding = this.getOwnerComponent().getModel().bindList(                                                                                                                                                                                     
                sPath,                                                                                                                                                                                                                                         
                undefined,                                                                                                                                                                                                                                     
                aSorters,                                                                                                                                                                                                                                      
                aFilters,                                                                                                                                                                                                                                      
                sSelect ? { $select: sSelect } : undefined                                                                                                                                                                                                     
            );                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                               
            try {                                                                                                                                                                                                                                              
                const aContexts = await oBinding.requestContexts(0, 1000);                                                                                                                                                                                     
                return aContexts.map((oContext) => ({ ...oContext.getObject() }));                                                                                                                                                                             
            } finally {                                                                                                                                                                                                                                        
                oBinding.destroy();                                                                                                                                                                                                                            
            }                                                                                                                                                                                                                                                  
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        // 서치헬프 후보 중복 제거                                                                                                                                                                                                                                       
        // - 생산오더 목록에는 같은 자재/공정이 여러 행으로 반복된다.                                                                                                                                                                                                                  
        // - 사용자에게는 같은 후보를 한 번만 보여주는 게 자연스럽기 때문에 key 기준으로 Map에 담는다.                                                                                                                                                                                            
        // - key는 실제 Input에 들어갈 값, text는 SelectDialog의 설명 영역에 표시할 값이다.                                                                                                                                                                                         
        _toDistinctValueHelpItems(aRows, sKeyField, sTextField) {                                                                                                                                                                                              
            const mSeen = new Map();                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                               
            aRows.forEach((oRow) => {                                                                                                                                                                                                                          
                const sKey = String(oRow[sKeyField] || "").trim();                                                                                                                                                                                             
                                                                                                                                                                                                                                                               
                if (!sKey || mSeen.has(sKey)) {                                                                                                                                                                                                                
                    return;                                                                                                                                                                                                                                    
                }                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                               
                mSeen.set(sKey, {                                                                                                                                                                                                                              
                    key: sKey,                                                                                                                                                                                                                                 
                    text: String(oRow[sTextField] || "").trim(),                                                                                                                                                                                               
                    materialType: String(oRow.MaterialType || "").trim(),                                                                                                                                                                                      
                    baseUnit: String(oRow.BaseUnit || "").trim()                                                                                                                                                                                               
                });                                                                                                                                                                                                                                            
            });                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                               
            return Array.from(mSeen.values());                                                                                                                                                                                                                 
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        // 생산오더 생성 실행                                                                                                                                                                                                                                          
        // - 화면에서 필수값/수량/기간을 1차 검증한 뒤 RAP action을 호출한다.                                                                                                                                                                                                        
        // - 실제 BOM, 라우팅, 주차별 아이템, 투입자재 생성은 ABAP 쪽 CreateProductionOrder/PREPARE_ORDER 로직이 담당한다.                                                                                                                                                               
        // - 성공하면 팝업을 닫고 목록/KPI를 새로고침해서 방금 생성한 오더가 보이게 한다.                                                                                                                                                                                                     
        async _submitCreateOrder() {                                                                                                                                                                                                                           
            const oCreateModel = this.getView().getModel("createOrder");                                                                                                                                                                                       
            const oData = oCreateModel.getData();                                                                                                                                                                                                              
                                                                                                                                                                                                                                                               
            if (!oData.Plant || !oData.Material || !oData.BasicStartDate || !oData.BasicEndDate || !oData.OrderQty) {                                                                                                                                          
                MessageBox.warning("플랜트, 자재, 시작일, 종료일, 생산수량은 필수입니다.");                                                                                                                                                                                         
                return;                                                                                                                                                                                                                                        
            }                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
            if (Number(oData.OrderQty) <= 0) {                                                                                                                                                                                                                 
                MessageBox.warning("생산수량은 0보다 커야 합니다.");                                                                                                                                                                                                       
                return;                                                                                                                                                                                                                                        
            }                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
            if (oData.BasicStartDate > oData.BasicEndDate) {                                                                                                                                                                                                   
                MessageBox.warning("종료일은 시작일보다 빠를 수 없습니다.");                                                                                                                                                                                                   
                return;                                                                                                                                                                                                                                        
            }                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
            const oAction = this.getOwnerComponent()                                                                                                                                                                                                           
                .getModel("orderCreate")                                                                                                                                                                                                                       
                .bindContext("/ProductionOrder/com.sap.gateway.srvd.zrap_c1_pp_0003_srv.v0001.CreateProductionOrder(...)");                                                                                                                                    
                                                                                                                                                                                                                                                               
            oAction.setParameter("Plant", oData.Plant.trim());                                                                                                                                                                                                 
            oAction.setParameter("Material", oData.Material.trim());                                                                                                                                                                                           
            oAction.setParameter("BasicStartDate", oData.BasicStartDate);                                                                                                                                                                                      
            oAction.setParameter("BasicEndDate", oData.BasicEndDate);                                                                                                                                                                                          
            oAction.setParameter("OrderQty", String(oData.OrderQty));                                                                                                                                                                                          
            oAction.setParameter("BaseUnit", (oData.BaseUnit || "EA").trim());                                                                                                                                                                                 
            oAction.setParameter("StorageLocation", (oData.StorageLocation || "SL30").trim());                                                                                                                                                                 
                                                                                                                                                                                                                                                               
            oCreateModel.setProperty("/busy", true);                                                                                                                                                                                                           
                                                                                                                                                                                                                                                               
            try {                                                                                                                                                                                                                                              
                await oAction.execute();                                                                                                                                                                                                                       
                this._oCreateOrderDialog.close();                                                                                                                                                                                                              
                MessageToast.show("생산오더를 생성했습니다.");                                                                                                                                                                                                            
                this.onRefresh();                                                                                                                                                                                                                              
            } catch (oError) {                                                                                                                                                                                                                                 
                MessageBox.error(this._getErrorMessage(oError) || "생산오더 생성 중 오류가 발생했습니다.");                                                                                                                                                                    
            } finally {                                                                                                                                                                                                                                        
                oCreateModel.setProperty("/busy", false);                                                                                                                                                                                                      
                oAction.destroy();                                                                                                                                                                                                                             
            }                                                                                                                                                                                                                                                  
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        _getErrorMessage(oError) {                                                                                                                                                                                                                             
            if (!oError) {                                                                                                                                                                                                                                     
                return "";                                                                                                                                                                                                                                     
            }                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
            if (oError.message) {                                                                                                                                                                                                                              
                return oError.message;                                                                                                                                                                                                                         
            }                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
            try {                                                                                                                                                                                                                                              
                const oResponse = JSON.parse(oError.responseText);                                                                                                                                                                                             
                return oResponse?.error?.message || "";                                                                                                                                                                                                        
            } catch (oParseError) {                                                                                                                                                                                                                            
                return "";                                                                                                                                                                                                                                     
            }                                                                                                                                                                                                                                                  
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        formatStatusState(sStatus) {                                                                                                                                                                                                                           
            if (sStatus === "DONE") {                                                                                                                                                                                                                          
                return "Success";                                                                                                                                                                                                                              
            }                                                                                                                                                                                                                                                  
            if (sStatus === "RUN") {                                                                                                                                                                                                                           
                return "Information";                                                                                                                                                                                                                          
            }                                                                                                                                                                                                                                                  
            return "Warning";                                                                                                                                                                                                                                  
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        formatHighlight(sStatus) {                                                                                                                                                                                                                             
            return this.formatStatusState(sStatus);                                                                                                                                                                                                            
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        formatProgress(iCompleted, iTotal) {                                                                                                                                                                                                                   
            const iSafeTotal = Number(iTotal) || 0;                                                                                                                                                                                                            
            return iSafeTotal ? Math.round((Number(iCompleted) || 0) / iSafeTotal * 100) : 0;                                                                                                                                                                  
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        formatProgressText(iCompleted, iTotal) {                                                                                                                                                                                                               
            return `${Number(iCompleted) || 0} / ${Number(iTotal) || 0} 공정`;                                                                                                                                                                                   
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        formatProgressPercentText(iCompleted, iTotal) {                                                                                                                                                                                                        
            return `${this.formatProgress(iCompleted, iTotal)}%`;                                                                                                                                                                                              
        },                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        formatProgressState(sStatus) {                                                                                                                                                                                                                         
            if (sStatus === "DONE") {                                                                                                                                                                                                                          
                return "Success";                                                                                                                                                                                                                              
            }                                                                                                                                                                                                                                                  
            if (sStatus === "WAIT") {                                                                                                                                                                                                                          
                return "None";                                                                                                                                                                                                                                 
            }                                                                                                                                                                                                                                                  
            return "Information";                                                                                                                                                                                                                              
        }                                                                                                                                                                                                                                                      
    });                                                                                                                                                                                                                                                        
});                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                               
